	mux.Close()
	mux.Wait()

	// use new client to use new connection pool
	client = cfg.NewClient()
	re, err = client.Get(url)
	if err == nil {
		re.Body.Close()
	}
	require.NotNil(t, err)

	httpServer.Close()
	s.Stop()
	// wait for both servers to finish
	for i := 0; i < 2; i++ {
		err := <-errCh
		require.Nil(t, err)
