func detect(conn net.Conn, enableProxyProtocol bool) (*Conn, error) {
	reader := bufio.NewReader(conn)

	// the first attempt is to parse optional proxy
	// protocol line that is injected by load balancers
	// before actual protocol traffic flows.
	// if the first attempt encounters proxy it
	// goes to the second pass to do protocol detection
	var proxyLine *ProxyLine
	for i := 0; i < 2; i++ {
		proto, err := detectProto(reader)
		if err != nil {
			return nil, trace.Wrap(err)
		}

		switch proto {
		case ProtoProxy:
			if !enableProxyProtocol {
				return nil, trace.BadParameter("proxy protocol support is disabled")
			}
			if proxyLine != nil {
				return nil, trace.BadParameter("duplicate proxy line")
			}
			proxyLine, err = ReadProxyLine(reader)
			if err != nil {
				return nil, trace.Wrap(err)
			}
		case ProtoProxyV2:
			if !enableProxyProtocol {
				return nil, trace.BadParameter("proxy protocol support is disabled")
			}
			if proxyLine != nil {
				return nil, trace.BadParameter("duplicate proxy line")
			}
			proxyLine, err = ReadProxyLineV2(reader)
			if err != nil {
				return nil, trace.Wrap(err)
			}
			// repeat the cycle to detect the protocol
		case ProtoTLS, ProtoSSH, ProtoHTTP:
			var clientAddr net.Addr
			if proto == ProtoSSH {
				// The SSH server consumes this hello to recover tracing context.
				// Inspect it here as well so the routed connection has the
				// correct remote address before the server reads from it.
				in, _ := reader.Peek(8) // detectProto already peeked eight bytes.
				if bytes.Equal(in, proxySSHPrefix[:8]) {
					clientAddr, reader, err = readProxySSHHello(reader)
					if err != nil {
						return nil, trace.Wrap(err)
					}
				}
			}
			return &Conn{
				protocol:   proto,
				Conn:       conn,
				reader:     reader,
				proxyLine:  proxyLine,
				clientAddr: clientAddr,
			}, nil
		case ProtoPostgres:
			return &Conn{
				protocol: proto,
				Conn:     conn,
				reader:   reader,
			}, nil
		}
	}
	// if code ended here after two attempts, something is wrong
	return nil, trace.BadParameter("unknown protocol")
}

// readProxySSHHello reads a bounded Teleport SSH hello and puts it back for
// the SSH server, which also uses the payload for tracing context.
func readProxySSHHello(reader *bufio.Reader) (net.Addr, *bufio.Reader, error) {
	const maxHelloBytes = 255 // SSH version string limit used by the SSH server.
	hello := make([]byte, 0, maxHelloBytes)
	for len(hello) < maxHelloBytes {
		b, err := reader.ReadByte()
		if err != nil {
			return nil, nil, trace.Wrap(err, "reading Teleport proxy hello")
		}
		hello = append(hello, b)
		if b == 0 {
			break
		}
	}
	if len(hello) == maxHelloBytes && hello[len(hello)-1] != 0 {
		return nil, nil, trace.BadParameter("Teleport proxy hello is too long")
	}
	var payload sshutils.HandshakePayload
	if err := json.Unmarshal(hello[len(sshutils.ProxyHelloSignature):len(hello)-1], &payload); err != nil {
		return nil, nil, trace.Wrap(err, "invalid Teleport proxy hello")
	}
	var clientAddr net.Addr
	if payload.ClientAddr != "" {
		host, port, err := net.SplitHostPort(payload.ClientAddr)
		if err != nil {
			return nil, nil, trace.Wrap(err, "invalid Teleport proxy client address")
		}
		portNumber, err := strconv.Atoi(port)
		if err != nil || portNumber < 0 || portNumber > 65535 || net.ParseIP(host) == nil {
			return nil, nil, trace.BadParameter("invalid Teleport proxy client address")
		}
		clientAddr = &net.TCPAddr{IP: net.ParseIP(host), Port: portNumber}
	}
	return clientAddr, bufio.NewReader(io.MultiReader(bytes.NewReader(hello), reader)), nil
}

